import heapq
import itertools


class Helpdesk:
    PRIORITIES = ("normal", "high", "critical")

    def __init__(self) -> None:
        self._customers = {}  # name -> vip
        self._tickets = {}    # id -> {
                              #   "title": str,
                              #   "priority": str,
                              #   "customer": str,
                              #   "state": "open" | "in_queue" | "closed",
                              # }
        self._next_id = 1
        self._counter = itertools.count()  # tiebreaker for FIFO within same priority
        self._queue = []  # heap entries: (-vip, -priority_rank, counter, ticket_id)

    def add_customer(self, name: str, vip: bool = False) -> None:
        self._customers[name] = vip

    def _priority_rank(self, priority: str) -> int:
        if priority not in self.PRIORITIES:
            raise ValueError(f"Unknown priority: {priority!r}")
        return self.PRIORITIES.index(priority)

    def _enqueue(self, ticket_id: int) -> None:
        t = self._tickets[ticket_id]
        vip = self._customers.get(t["customer"], False)
        rank = self._priority_rank(t["priority"])
        # Higher vip first (-vip), higher priority first (-rank), then FIFO.
        heapq.heappush(
            self._queue,
            (-int(vip), -rank, next(self._counter), ticket_id),
        )
        t["state"] = "in_queue"

    def open_ticket(self, customer: str, title: str, priority: str = "normal") -> int:
        if not title:
            raise ValueError("Ticket title must not be empty.")
        if priority not in self.PRIORITIES:
            raise ValueError(f"Unknown priority: {priority!r}")
        if customer not in self._customers:
            raise ValueError(f"Unknown customer: {customer!r}")

        ticket_id = self._next_id
        self._next_id += 1
        self._tickets[ticket_id] = {
            "title": title,
            "priority": priority,
            "customer": customer,
            "state": "open",
        }
        self._enqueue(ticket_id)
        return ticket_id

    def next_ticket(self) -> int | None:
        while self._queue:
            _, _, _, ticket_id = heapq.heappop(self._queue)
            t = self._tickets[ticket_id]
            if t["state"] == "in_queue":
                return ticket_id
        return None

    def close(self, ticket_id: int) -> None:
        if ticket_id not in self._tickets:
            raise ValueError(f"Unknown ticket id: {ticket_id!r}")
        self._tickets[ticket_id]["state"] = "closed"

    def reopen(self, ticket_id: int) -> None:
        if ticket_id not in self._tickets:
            raise ValueError(f"Unknown ticket id: {ticket_id!r}")
        t = self._tickets[ticket_id]
        if t["state"] == "closed":
            raise ValueError("A closed ticket cannot be reopened.")
        # Only re-enqueue if it was taken out of the queue (in handling) but not closed.
        if t["state"] == "open":
            self._enqueue(ticket_id)
        # If already "in_queue", do nothing (it's still queued).
```

Key design decisions:

- **VIP precedence**: The heap key begins with `-int(vip)`, so VIP tickets always pop before non-VIP, regardless of priority. Priority rank follows as the second key, then an `itertools.count()` tiebreaker ensures FIFO within the same (VIP, priority) class.
- **Lazy deletion**: `close()` just marks the ticket `closed`; the stale heap entry is skipped in `next_ticket()`.
- **`next_ticket()` semantics**: it removes the ticket from the queue but does *not* close it — that mirrors helpdesk agents "taking" a ticket. Calling `reopen()` on such an in-handling ticket re-queues it; calling `reopen()` on a `closed` ticket raises `ValueError` per requirement 2.
- **Validation**: Empty titles and unknown priorities/customers raise `ValueError`.

